  }
  if(sql.includes('FROM public."ProjectMembership"'))return rows(controls.projectMembership?[{id:'assignment_worker',revision}]:[]);
  if(sql.startsWith('SELECT w.id'))return rows(controls.duplicate?[{id:'worker_duplicate'}]:[]);
