}

function records(text,delimiter){
 const result=parse(text,delimiter);
 if(!result.length||!same(result[0].cells,PLAN_BUDGET_CSV_HEADERS))fail('PLAN_IMPORT_BUDGET_CSV_HEADERS_INVALID');
