let pilotPreviousReader=null;
function historicalPilotSourceReader(){
 if(pilotPreviousReader)return pilotPreviousReader;
 const previous=restorePilotCompletionPreviousContract(authenticatedContract,read),changes=new Map(authenticatedContract.planBudgetCurrentRevision.pilotCompletionAdvance.sourceChanges.map(row=>[row.path,row]));
 const cache=new Map([['.github/workspace-acceptance-contract.json',Buffer.from(JSON.stringify(previous,null,2)+'\n')]]);
 pilotPreviousReader=file=>{
  if(changes.get(file)?.status==='ADDED')return null;
  if(cache.has(file))return Buffer.from(cache.get(file));
  let actual;try{actual=read(file);}catch(error){if(error.code==='ENOENT'||error.code==='EISDIR')return null;throw error;}
  if(actual===null)return null;
  const decoded=actual.toString('utf8');assert.equal(actual.equals(Buffer.from(decoded)),true,'Historical source must be UTF-8: '+file);
  const text=changes.has(file)||file==='scripts/lib/plan-budget-current-ci-reviewed.mjs'?restorePilotCompletionPreviousSourceText(authenticatedContract,file,decoded):decoded.replaceAll('\r\n','\n');
  const bytes=Buffer.from(text);cache.set(file,bytes);return Buffer.from(bytes);
 };
 return pilotPreviousReader;
}

